// Sandbox verification: create a paid invoice, then reverse it with the canonical 2-call path
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const headers = { Authorization: AUTH, "Content-Type": "application/json" };

const TODAY = "2026-03-21";

// Step 0a: Find or create a customer
const custSearch = await fetch(`${BASE}/customer?organizationNumber=910318144&fields=id,name`, { headers });
const custData = await custSearch.json();
let customerId: number;
if (custData.count > 0) {
  customerId = custData.values[0].id;
  console.log("Found existing customer:", customerId);
} else {
  const custCreate = await fetch(`${BASE}/customer`, {
    method: "POST",
    headers,
    body: JSON.stringify({ name: "Sierra SL", organizationNumber: "910318144" })
  });
  const custResult = await custCreate.json();
  customerId = custResult.value.id;
  console.log("Created customer:", customerId);
}

// Step 0b: Create an order with a line
const orderRes = await fetch(`${BASE}/order`, {
  method: "POST",
  headers,
  body: JSON.stringify({
    customer: { id: customerId },
    deliveryDate: TODAY,
    orderDate: TODAY,
    orderLines: [{ description: "Almacenamiento en la nube", count: 1, unitPriceExcludingVatCurrency: 19250 }]
  })
});
const orderData = await orderRes.json();
const orderId = orderData.value.id;
console.log("Created order:", orderId);

// Step 0c: Invoice the order
const invoiceRes = await fetch(`${BASE}/order/${orderId}/:invoice?invoiceDate=${TODAY}&sendToCustomer=false`, {
  method: "PUT",
  headers
});
const invoiceData = await invoiceRes.json();
const invoiceId = invoiceData.value.id;
console.log("Created invoice:", invoiceId);

// Step 0d: Pay the invoice
const paymentTypeRes = await fetch(`${BASE}/ledger/paymentType?fields=id,description&count=10`, { headers });
const ptData = await paymentTypeRes.json();
const paymentType = ptData.values[0];
console.log("Payment type:", paymentType.id, paymentType.description);

const payRes = await fetch(`${BASE}/invoice/${invoiceId}/:payment?paymentDate=${TODAY}&paymentTypeId=${paymentType.id}&paidAmount=24062.5&paidAmountCurrency=24062.5`, {
  method: "PUT",
  headers
});
if (!payRes.ok) {
  // Try with the gross amount from the invoice
  const invRead = await fetch(`${BASE}/invoice/${invoiceId}?fields=amountCurrency,amountExcludingVatCurrency`, { headers });
  const invData = await invRead.json();
  console.log("Invoice amounts:", invData.value);
  const gross = invData.value.amountCurrency;
  const payRes2 = await fetch(`${BASE}/invoice/${invoiceId}/:payment?paymentDate=${TODAY}&paymentTypeId=${paymentType.id}&paidAmount=${gross}&paidAmountCurrency=${gross}`, {
    method: "PUT",
    headers
  });
  console.log("Payment retry:", payRes2.status);
}
const payData = await payRes.json();
console.log("Payment response:", JSON.stringify(payData).substring(0, 200));

console.log("\n=== Now testing the canonical 2-call reverse path ===\n");

// CALL 1: Decisive GET to locate the paid invoice
const url1 = `${BASE}/invoice?customerOrgNumber=910318144&invoiceDateFrom=2000-01-01&invoiceDateTo=2026-12-31&count=100&fields=*,customer(*),orderLines(*),orders(*),postings(*,voucher(*),account(*),customer(*),closeGroup(*))`;
console.log("CALL 1: GET", url1.substring(BASE.length));
const r1 = await fetch(url1, { headers });
const data1 = await r1.json();
console.log("Invoice count:", data1.count);

// Find the target invoice (the one we just created, with ex-VAT 19250)
const invoices = data1.values as any[];
const target = invoices.find((inv: any) => inv.id === invoiceId) || invoices.find((inv: any) => inv.amountExcludingVatCurrency === 19250);

if (!target) {
  console.error("No matching invoice found! Trying direct GET...");
  // Sandbox trap: broad search may not return fresh invoices
  const directRes = await fetch(`${BASE}/invoice/${invoiceId}?fields=*,customer(*),orderLines(*),orders(*),postings(*,voucher(*),account(*),customer(*),closeGroup(*))`, { headers });
  const directData = await directRes.json();
  console.log("Direct GET invoice:", directData.value?.id, "postings count:", directData.value?.postings?.length);
  // Continue with directData.value
  const inv = directData.value;
  const postings = inv.postings as any[];
  const paymentPostings = postings.filter((p: any) => {
    if (p.amountCurrency >= 0) return false;
    if (p.description && p.description.startsWith("Betaling:")) return true;
    if (p.type === "INCOMING_PAYMENT" || p.type === "INCOMING_PAYMENT_OPPOSITE") return true;
    return false;
  });
  const paymentVoucherIds = [...new Set(paymentPostings.map((p: any) => p.voucher?.id).filter(Boolean))];
  console.log("Payment voucher ids:", paymentVoucherIds);
  if (paymentVoucherIds.length === 1) {
    const reverseUrl = `${BASE}/ledger/voucher/${paymentVoucherIds[0]}/:reverse?date=${TODAY}`;
    console.log("CALL 2 (fallback): PUT", reverseUrl.substring(BASE.length));
    const r2 = await fetch(reverseUrl, { method: "PUT", headers });
    const data2 = await r2.json();
    console.log("Reverse voucher id:", data2.value?.id);
  }
} else {
  console.log("Target invoice id:", target.id, "amountCurrency:", target.amountCurrency, "amountExcludingVatCurrency:", target.amountExcludingVatCurrency);
  console.log("Postings count:", target.postings?.length);

  const postings = target.postings as any[];
  for (const p of postings) {
    console.log(`  posting: amount=${p.amountCurrency}, desc="${p.description}", type=${p.type}, voucher=${p.voucher?.id}, account=${p.account?.number}`);
  }

  const paymentPostings = postings.filter((p: any) => {
    if (p.amountCurrency >= 0) return false;
    if (p.description && p.description.startsWith("Betaling:")) return true;
    if (p.type === "INCOMING_PAYMENT" || p.type === "INCOMING_PAYMENT_OPPOSITE") return true;
    return false;
  });
  const paymentVoucherIds = [...new Set(paymentPostings.map((p: any) => p.voucher?.id).filter(Boolean))];
  console.log("Payment voucher ids:", paymentVoucherIds);

  if (paymentVoucherIds.length === 1) {
    // CALL 2: Reverse the payment voucher
    const reverseUrl = `${BASE}/ledger/voucher/${paymentVoucherIds[0]}/:reverse?date=${TODAY}`;
    console.log("CALL 2: PUT", reverseUrl.substring(BASE.length));
    const r2 = await fetch(reverseUrl, { method: "PUT", headers });
    if (!r2.ok) { console.error("PUT reverse failed:", r2.status, await r2.text()); process.exit(1); }
    const data2 = await r2.json();
    console.log("Reverse voucher id:", data2.value?.id);
  }
}

// Verify: check the invoice outstanding amount
const verifyRes = await fetch(`${BASE}/invoice/${invoiceId}?fields=amountCurrency,amountCurrencyOutstanding,amountOutstanding`, { headers });
const verifyData = await verifyRes.json();
console.log("\nVerification - invoice amounts after reversal:");
console.log("  amountCurrency:", verifyData.value?.amountCurrency);
console.log("  amountCurrencyOutstanding:", verifyData.value?.amountCurrencyOutstanding);
console.log("  amountOutstanding:", verifyData.value?.amountOutstanding);
console.log("\nSandbox verification complete.");

