// Sandbox verification: pay an existing invoice, then reverse it with the canonical 2-call path
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const headers = { Authorization: AUTH, "Content-Type": "application/json" };

const TODAY = "2026-03-21";

// Find the invoice we just created (id 2147637165)
const invoiceId = 2147637165;

// Find a payment type
const ptRes = await fetch(`${BASE}/ledger/paymentType/outgoing?fields=id,description&count=10`, { headers });
if (!ptRes.ok) {
  console.log("paymentType/outgoing failed:", ptRes.status);
  // Try without outgoing
  const ptRes2 = await fetch(`${BASE}/ledger/paymentType?count=10`, { headers });
  console.log("paymentType status:", ptRes2.status);
  const ptData2 = await ptRes2.json();
  console.log("paymentType response:", JSON.stringify(ptData2).substring(0, 500));
}
const ptData = await ptRes.json();
console.log("paymentType response:", JSON.stringify(ptData).substring(0, 500));

// Get the invoice to see its gross amount
const invRes = await fetch(`${BASE}/invoice/${invoiceId}?fields=amountCurrency,amountExcludingVatCurrency,amountCurrencyOutstanding`, { headers });
const invData = await invRes.json();
console.log("Invoice:", invData.value);
const gross = invData.value?.amountCurrency;

if (!gross) {
  console.error("Invoice not found or no gross amount");
  process.exit(1);
}

// Pay the invoice - find payment types
const ptRes3 = await fetch(`${BASE}/invoice/${invoiceId}/:payment?paymentDate=${TODAY}&paymentTypeId=1&paidAmount=${gross}&paidAmountCurrency=${gross}`, {
  method: "PUT",
  headers
});
console.log("Payment attempt status:", ptRes3.status);
if (!ptRes3.ok) {
  const errText = await ptRes3.text();
  console.log("Payment error:", errText);

  // Try paymentTypeId=2
  const ptRes4 = await fetch(`${BASE}/invoice/${invoiceId}/:payment?paymentDate=${TODAY}&paymentTypeId=2&paidAmount=${gross}&paidAmountCurrency=${gross}`, {
    method: "PUT",
    headers
  });
  console.log("Payment attempt 2 status:", ptRes4.status);
  if (!ptRes4.ok) {
    console.log("Payment error 2:", await ptRes4.text());
  } else {
    console.log("Payment 2 response:", JSON.stringify(await ptRes4.json()).substring(0, 200));
  }
} else {
