// Sandbox: create paid invoice then reverse with 2-call path
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const headers = { Authorization: AUTH, "Content-Type": "application/json" };
const TODAY = "2026-03-21";

// Use the invoice already created: 2147637165 with amount 19250 (no VAT in sandbox)
const invoiceId = 2147637165;

// Find payment types - search for bank type
const ptRes = await fetch(`${BASE}/ledger/paymentType/outgoing?count=50`, { headers });
console.log("paymentType/outgoing:", ptRes.status);

// Use the approach from register-customer-invoice-payment trusted standard
// PUT /invoice/{id}/:payment needs a paymentTypeId - let's find them
const ptSearch = await fetch(`${BASE}/ledger/paymentType?count=50&fields=id,description`, { headers });
console.log("ledger/paymentType:", ptSearch.status);

// Maybe the endpoint is different in sandbox
const ptSearch2 = await fetch(`${BASE}/invoice/paymentType?count=50&fields=id,description`, { headers });
console.log("invoice/paymentType:", ptSearch2.status);
if (ptSearch2.ok) {
  const d = await ptSearch2.json();
  console.log("invoice/paymentType data:", JSON.stringify(d).substring(0, 500));
}

// Try direct payment with known payment type IDs from previous sandbox proofs
const ptSearch3 = await fetch(`${BASE}/ledger/paymentType/outgoing?count=50&fields=id,description`, { headers });
console.log("ledger/paymentType/outgoing:", ptSearch3.status);

// Try to pay using the order/:invoice flow with paymentTypeId instead
// First check what payment types exist on the system
const endpoints = [
  "/invoice/paymentType",
  "/ledger/paymentType",
];
for (const ep of endpoints) {
  const r = await fetch(`${BASE}${ep}?count=5`, { headers });
  if (r.ok) {
    const d = await r.json();
    console.log(`${ep}:`, JSON.stringify(d).substring(0, 300));
  } else {
    console.log(`${ep}: ${r.status}`);
  }
}
